import{_ as n,a as r,b as t,c as i,d as a,e as s,f as l,g as h,h as u,i as d,j as o,k as c}from"./chunks/ha-177-restore-0.1.7.DjNsqWR9.js";import{_ as g,o as p,c as b,a3 as f}from"./chunks/framework.BlfGB29P.js";const m="/images/dashboard-user-manager/ha-177-de-0.1.10.png",k="/images/dashboard-user-manager/selection-177-de-0.1.5.png",w="/images/dashboard-user-manager/ha-177-save-de-0.1.8.png",H=JSON.parse('{"title":"Dashboard-Benutzerverwaltung","description":"Benutzer für alle HA-Ansichten oder einzeln per Checkbox zuordnen, mit Sicherung und DE/EN/FR.","frontmatter":{"title":"Dashboard-Benutzerverwaltung","description":"Benutzer für alle HA-Ansichten oder einzeln per Checkbox zuordnen, mit Sicherung und DE/EN/FR."},"headers":[],"relativePath":"projects/dashboard-user-manager/index.md","filePath":"projects/dashboard-user-manager/index.md","lastUpdated":1792850658000}'),A={name:"projects/dashboard-user-manager/index.md"};function v(S,e,z,D,P,E){return p(),b("div",null,[...e[0]||(e[0]=[f('<h1 id="dashboard-benutzerverwaltung" tabindex="-1">Dashboard-Benutzerverwaltung <a class="header-anchor" href="#dashboard-benutzerverwaltung" aria-label="Permalink to &quot;Dashboard-Benutzerverwaltung&quot;">​</a></h1><p><strong>Version 0.1.11 · DE / EN / FR · MIT · stabil</strong></p><img src="'+n+'" width="96" height="96" alt="App-Icon mit Dashboard-Matrix, Benutzern und Häkchen"><p>Ab 0.1.7 ist das eigene PNG-Icon in der HA-App-Kachel, im Kopf der Oberfläche und als App-Favicon enthalten. Das freigegebene Motiv ist in ZIP und UGSo-Paket vollständig enthalten und benötigt keinen externen Bilddienst. Die HA-Seitenleiste behält ihr konfiguriertes MDI-Symbol. Einstellungen, gespeicherte Vorauswahl und Dashboard-Daten bleiben beim Icon-Update erhalten.</p><p>Eine eigenständige HA-App: Dashboards auswählen, Benutzer als Spalten und Ansichten als Zeilen anzeigen und die Zuordnung per Checkbox bearbeiten. Kein ATLAS erforderlich. Die breite Oberfläche nutzt 90 vw und 90 vh; die Checkbox-Tabelle hat eine eigene begrenzte Höhe und scrollt vertikal sowie bei Bedarf horizontal. Innerhalb der Tabelle wischen oder den Scrollbereich fokussieren und Pfeiltasten/Bild auf/Bild ab verwenden. Ansichtennamen und Benutzerköpfe bleiben fixiert; niedrige Displays verwenden kürzere Köpfe. Außerhalb der Tabelle scrollt die übrige Seite.</p><p><img src="'+r+'" alt="Vertikale und horizontale Scrollfläche in 0.1.11 auf .177 bei 390 × 844 Pixeln"></p><p><img src="'+m+'" alt="Stabile Dashboard-Benutzerverwaltung 0.1.10 nach Wiederherstellung auf .177"></p><p>Echte Aufnahme vom Testsystem .177, 20.10.2026, nach vollständiger Wiederherstellung und Update auf 0.1.10: deutsche Oberfläche, 18 Ansichten und vier Benutzer. Das vorhandene Dashboard wurde nicht geändert.</p><h2 id="installation-uber-ugso-ha-apps" tabindex="-1">Installation über UGSo HA Apps <a class="header-anchor" href="#installation-uber-ugso-ha-apps" aria-label="Permalink to &quot;Installation über UGSo HA Apps&quot;">​</a></h2><p>Zuerst ein vollständiges HA-Backup erstellen. Unter <strong>Einstellungen → Apps → App-Store → Repositorys</strong> hinzufügen:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Die <strong>Dashboard-Benutzerverwaltung</strong> installieren, starten und über HA Ingress öffnen. Die Oberfläche ist ausschließlich für aktive HA-Administratoren zugänglich. Kein zusätzlicher LAN-Port, kein manuell einzutragender Token. Benötigt Home Assistant mit Supervisor und ein manuell verwaltetes Dashboard. YAML- und automatisch erzeugte Dashboards sind nur lesbar.</p><p>Eine vorhandene <strong>lokale App</strong> bleibt beim Hinzufügen des Repositorys unverändert. Lokale und Repository-App besitzen verschiedene Kennungen und getrennte private App-Daten. Vor einem bewussten Quellenwechsel Vollbackup einschließlich der bisherigen App und deren JSON-Sicherungen herunterladen. Die lokale App nicht ungeprüft deinstallieren; nur eine App gleichzeitig zum Bearbeiten verwenden.</p><h2 id="dashboards-filtern-und-vorauswahlen" tabindex="-1">Dashboards filtern und vorauswählen <a class="header-anchor" href="#dashboards-filtern-und-vorauswahlen" aria-label="Permalink to &quot;Dashboards filtern und vorauswählen&quot;">​</a></h2><p>Ab 0.1.6 erscheint eine von HA migrierte Übersicht nur einmal: Der Eintrag <code>lovelace</code> und sein alter Standardzugang werden zusammengeführt. Eine zuvor über einen der beiden Einträge gespeicherte Vorauswahl bleibt erhalten. Gleichnamige Dashboards mit verschiedenen tatsächlichen Pfaden bleiben getrennt; Titel allein sind kein Dublettenkriterium. Ältere Dashboard-Sicherungen bleiben verwendbar. Grundlage ist die <a href="https://github.com/home-assistant/core/blob/2026.10.2/homeassistant/components/lovelace/websocket.py" target="_blank" rel="noreferrer">HA-Zuordnung des Standardzugangs</a>.</p><p><img src="'+k+`" alt="Dashboard-Vorauswahl 0.1.5 mit Checkboxen auf .177"></p><p>Die Dropdownliste enthält nur erfolgreich geladene Dashboards mit mindestens einer Ansicht. Bestätigte leere Einträge und App-Seiten ohne Ansichten werden ausgeblendet. Ladefehler erscheinen getrennt mit Dashboard-Namen und gelten nicht als leer; über <strong>Neu laden</strong> erneut prüfen. YAML- oder generierte Dashboards mit Ansichten bleiben als <strong>nur lesbar</strong> gekennzeichnet.</p><p><strong>Dashboard-Vorauswahl</strong> öffnet ein Fenster mit einer Checkbox je verfügbarem Dashboard, <strong>Alle auswählen</strong>, <strong>Alle abwählen</strong>, <strong>Abbrechen</strong> und <strong>Vorauswahl übernehmen</strong>. Nur angehakte Einträge erscheinen anschließend im Dropdown. Die Auswahl wird pro Browser und HA-Adresse gespeichert; sie ändert keine Dashboards oder Benutzerzuordnungen. Auch eine leere Auswahl ist erlaubt. Nach einer gespeicherten Vorauswahl neue Dashboards bei Bedarf dort ergänzen. Bei Ladefehlern bleiben frühere Auswahlpräferenzen erhalten.</p><p>Bleibt das aktuelle Dashboard ausgewählt, bleiben auch ungespeicherte Zuordnungen erhalten. Wird es abgewählt, fragt die App vor dem Verwerfen ungespeicherter Änderungen nach. Bei gesperrtem Browser-Speicher zeigt sie einen Fehler und übernimmt die Vorauswahl nicht scheinbar erfolgreich.</p><h2 id="benutzer-zuordnen" tabindex="-1">Benutzer zuordnen <a class="header-anchor" href="#benutzer-zuordnen" aria-label="Permalink to &quot;Benutzer zuordnen&quot;">​</a></h2><ol><li>Dashboard wählen. Alle Ansichten einschließlich Unteransichten werden aufgelistet.</li><li>Im Spaltenkopf beispielsweise <strong>webuser</strong> auswählen: Der Benutzer wird für alle bearbeitbaren Ansichten angehakt. Abwählen entfernt ihn aus diesen Ansichten.</li><li>Einzelne Checkboxen pro Ansicht korrigieren. Ein Strich im Spaltenkopf bedeutet teilweise ausgewählt.</li><li><strong>Änderungen speichern</strong>. Erst jetzt werden Dashboard-Sicherung und Schreibvorgang ausgeführt. <strong>Auswahl zurücksetzen</strong> verwirft ausschließlich ungespeicherte Änderungen.</li></ol><p><strong>Grünes U = Benutzer, rotes A = Administrator.</strong> Die Rollen selbst werden nicht geändert. Eigene Dashboard-, Ansichts- und Benutzernamen, Karten, Layouts, Pfade und nicht bearbeitete Ansichten bleiben erhalten. Frühere Benutzer-IDs werden nicht stillschweigend gelöscht. Bearbeitete Ansichten erhalten feste Listen; neu angelegte Benutzer werden dort später nicht automatisch ergänzt.</p><div class="warning custom-block"><p class="custom-block-title">Sichtbarkeit ist keine Zugriffssperre</p><p>Die App steuert die Sichtbarkeit der Ansichts-Tabs. Direkte URLs bleiben erreichbar; das ersetzt keine HA-Zugriffsrechte. Siehe <a href="https://www.home-assistant.io/dashboards/views/#visible" target="_blank" rel="noreferrer">offizielle HA-Dokumentation</a>.</p></div><h2 id="zeitlimit-abbruch-und-entwurf" tabindex="-1">Zeitlimit, Abbruch und Entwurf <a class="header-anchor" href="#zeitlimit-abbruch-und-entwurf" aria-label="Permalink to &quot;Zeitlimit, Abbruch und Entwurf&quot;">​</a></h2><p>Ab 0.1.9 endet das Warten beim Speichern spätestens nach 30 Sekunden. <strong>Warten abbrechen</strong> beendet es früher. Die Checkbox-Auswahl bleibt erhalten; <strong>Entwurf sichern</strong> lädt die geplanten Zuordnungen als lokale JSON-Datei herunter. Diese Datei ist ein Entwurfsnachweis, kein vollständiges Dashboard-Backup und kein automatisch rückimportierbares Projekt. Vor dem Schließen des Tabs sichern.</p><p>Wurde noch kein Schreibauftrag gesendet, kann nach Behebung der Ursache erneut gespeichert werden. Bei <strong>Speicherergebnis unklar</strong> bleibt Speichern gesperrt: <strong>Serverstand prüfen</strong> liest den tatsächlichen Stand und verhindert die spätere Ausführung eines noch unbenutzten Speicherplans. Bereits gespeicherter Entwurf, unveränderter Server und zwischenzeitliche Änderungen werden unterschieden; die Prüfung schreibt nicht erneut. Auch sie ist zeitlich begrenzt und abbrechbar. Bei einem Konflikt zuerst den Entwurf sichern und anschließend bewusst neu laden.</p><p>Abbrechen beendet nur das lokale Warten; ein bereits beim Server eingegangener Schreibauftrag kann noch fertig werden. Deshalb nicht blind wiederholen. Nach einem App-Neustart kann eine neue Sitzung nötig sein: Entwurf zuerst sichern, anschließend die Sitzung neu laden und die gewünschten Änderungen gezielt übernehmen. Der Entwurf wird nicht automatisch nachgespeichert und überlebt ein Schließen/Neuladen nicht ohne die heruntergeladene Datei.</p><h2 id="automatische-sprache" tabindex="-1">Automatische Sprache <a class="header-anchor" href="#automatische-sprache" aria-label="Permalink to &quot;Automatische Sprache&quot;">​</a></h2><p><strong>Automatisch (Home Assistant)</strong> übernimmt die HA-Oberflächensprache. Ist der umgebende HA-Rahmen nicht lesbar, gilt die bevorzugte Browsersprache. Nicht unterstützte Sprachen verwenden Englisch. Oben lässt sich zusätzlich DE, EN oder FR auswählen; die Präferenz gilt nur für diesen Browser.</p><p>Die Übersetzung umfasst Beschriftungen, Hilfen, Dialoge, Status, Datumsanzeigen, Barrierefreiheit und Servermeldungen. Ungespeicherte Checkboxen bleiben beim Sprachwechsel erhalten. Eigene Namen und gespeicherte Dashboard-Daten werden nicht übersetzt. Keine Cloud-Übersetzung oder zusätzlichen Schlüssel erforderlich.</p><h2 id="sicherungen-und-konflikte" tabindex="-1">Sicherungen und Konflikte <a class="header-anchor" href="#sicherungen-und-konflikte" aria-label="Permalink to &quot;Sicherungen und Konflikte&quot;">​</a></h2><p>Vor jeder Änderung entsteht eine vollständige Dashboard-JSON unter <code>/data/backups/</code> im privaten App-Speicher. Über <strong>JSON sichern</strong> herunterladen. Die Dateien enthalten alle Kartenkonfigurationen und müssen vertraulich aufbewahrt werden. App-Updates erhalten diesen Speicher; vor einer Deinstallation herunterladen oder in einem HA-Backup sichern.</p><p>Die App vergleicht Dashboard und Benutzerliste mit dem geladenen Stand und prüft nach dem Schreiben das Ergebnis. Zwischenzeitliche Änderungen sperren das Speichern. HA bietet kein atomares Vergleich-und-Speichern: während der kurzen Speicherphase nicht parallel in einem anderen Editor bearbeiten.</p><p>Eine Wiederherstellung sichert zuvor erneut und wird gesperrt, wenn das Dashboard nach der betreffenden Änderung weiter bearbeitet wurde. Bei unbestätigtem Speichern nicht blind wiederholen, sondern aktuellen Stand und Sicherung prüfen.</p><h2 id="app-oder-vollstandiges-ha-backup-wiederherstellen" tabindex="-1">App oder vollständiges HA-Backup wiederherstellen <a class="header-anchor" href="#app-oder-vollstandiges-ha-backup-wiederherstellen" aria-label="Permalink to &quot;App oder vollständiges HA-Backup wiederherstellen&quot;">​</a></h2><p>Ein HA-Vollbackup muss die <strong>Dashboard-Benutzerverwaltung</strong> unter Apps enthalten: Dort liegen die privaten Dashboard-Sicherungen. Die eigentlichen Dashboards gehören zum HA-Konfigurationsanteil. Vor dem Rücksetzen eine frische vollständige Sicherung erstellen und keine parallelen Änderungen vornehmen.</p><p>Unter <strong>Einstellungen → System → Backups</strong> die passende Sicherung öffnen. Nur <strong>Dashboard-Benutzerverwaltung</strong> auswählen, um die App einschließlich ihrer privaten Sicherungen zurückzusetzen; die aktuelle HA-Dashboard-Konfiguration bleibt dabei bestehen. Für eine vollständige Wiederherstellung <strong>Home Assistant</strong>, Einstellungen/Verlauf, vorhandene Ordner und alle benötigten Apps auswählen. Dabei wird der gesamte ausgewählte Umfang auf den Sicherungszeitpunkt zurückgesetzt, einschließlich später angelegter Testobjekte. HA ist während seines Neustarts nicht erreichbar.</p><p>Nach Abschluss die App erneut über die HA-Seitenleiste öffnen. Version, vorhandene Dashboard-Sicherungen, Dashboard-/Benutzerzahl und Browser-Vorauswahl kontrollieren. Erst bei bestätigtem Serverstand weiter bearbeiten. Vollbackups und private Dashboard-JSON vertraulich aufbewahren; eine Browser-Vorauswahl ersetzt keine Datensicherung.</p><h2 id="lokale-zip-installation-aktualisieren" tabindex="-1">Lokale ZIP-Installation aktualisieren <a class="header-anchor" href="#lokale-zip-installation-aktualisieren" aria-label="Permalink to &quot;Lokale ZIP-Installation aktualisieren&quot;">​</a></h2><p>Nach Vollbackup die vollständigen neuen Quelldateien nach <code>/addons/dashboard_user_manager/</code> kopieren und im HA-Terminal ausführen:</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">touch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /addons/dashboard_user_manager/config.yaml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ha</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> store</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ha</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local_dashboard_user_manager</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Sobald <code>version_latest</code> die neue Version meldet, in HA aktualisieren. <code>touch</code> erneuert nur den Zeitstempel und hilft bei älteren ZIPs, deren erhaltene Zeitstempel Supervisor sonst nicht als Änderung erkennt. Nicht deinstallieren. Repository-Apps werden über ihr Repository aktualisiert.</p><h2 id="prufstand-und-grenzen" tabindex="-1">Prüfstand und Grenzen <a class="header-anchor" href="#prufstand-und-grenzen" aria-label="Permalink to &quot;Prüfstand und Grenzen&quot;">​</a></h2><p><strong>0.1.11 – Scrollkorrektur:</strong> Nutzerbefund: fehlende vertikale Bedienbarkeit auf BV6200 Pro mit Android 14/DokeOS 4.0, Samsung Tablet A6 mit Android 11, Companion-App und Chrome. Die Tabelle hat nun eine ausdrücklich vertikal scrollbar begrenzte Höhe, eine horizontale Scrollrichtung bei Platzmangel, Touch-Gesten und getrenntes Scrollen gegenüber der umgebenden Seite. Die Beschriftung nennt beide Richtungen in DE/EN/FR.</p><p>Nach frischem Vollbackup auf .177 von 0.1.10 auf 0.1.11 aktualisiert. Chrome-Prüfung mit 390 × 844, 844 × 390, 768 × 1024 und 1024 × 768 Pixeln: vertikales Scrollen bis zur letzten Ansicht möglich, im schmalen Handyformat auch horizontal. Köpfe und erste Spalte bleiben fixiert; sämtliche Checkbox-Zustände, 18 Ansichten, vier Benutzer, Vorauswahl und 17 private Sicherungen erhalten. Kein Speichern von Zuordnungen ausgeführt. Alle 23 geprüften ursprünglichen HA-Dateien bytegleich; Projekte, Plugins und Papierkorb unverändert. 33 Python- und 19 Node-Prüfungen sowie Docker-Builds amd64/arm64 bestanden.</p><p><strong>Geräteprüfung durch den Nutzer am 20.10.2026 bestätigt:</strong> Vertikales und horizontales Scrollen funktionieren mit 0.1.11 in der tatsächlichen Home-Assistant-Companion-App auf Handy und Tablet: BV6200 Pro mit Android 14/DokeOS 4.0 sowie Samsung Tablet A6 mit Android 11. Damit ist auch der zuvor ausstehende Finger-Scrolltest auf beiden Geräten erfolgreich abgeschlossen. Grundlage ist die ausdrückliche Nutzerrückmeldung; die oben dokumentierte Chrome-Prüfung bleibt als eigener Nachweis erhalten.</p><p><strong>0.1.10 – Serverausgänge „nicht gespeichert“ und „Konflikt“ auf .177 geprüft:</strong> Nach frischem Vollbackup wurde ausschließlich für das eigene Testdashboard der erste und dritte Schreibauftrag vor dem Senden an HA durch einen echten Socket-Abbruch verhindert. Die unveränderte App behandelte beide Ausgänge zunächst als unklar; alle Checkboxen des Entwurfs blieben erhalten. Kein Eingriff in Bestandsdashboards oder Zugriffsrechte.</p><ul><li><strong>Nicht gespeichert:</strong> HA-Datei vor und nach <strong>Serverstand prüfen</strong> exakt gleich zum Ausgangsstand. Meldung <strong>Serverstand ist unverändert. Dein Entwurf ist erhalten und kann erneut gespeichert werden.</strong> Speichern wird wieder freigegeben; der bewusst gestartete zweite Versuch speichert anschließend genau die beiden gewünschten Benutzerlisten und liest sie erfolgreich zurück.</li><li><strong>Konflikt:</strong> Nach dem dritten, ebenfalls verhinderten Schreibauftrag änderte eine zweite HA-Sitzung einen Karteninhalt im eigenen Dashboard. Die Serverprüfung erkannte die Abweichung, sperrte Speichern und erhielt den vollständigen Entwurf. <strong>Entwurf sichern</strong> lieferte eine geprüfte JSON mit beiden geplanten Zuordnungen ohne Zugangsdaten. Die Änderung der zweiten Sitzung blieb durch die Prüfung bytegleich erhalten; keine erneute HA-Schreiboperation.</li></ul><p>Alle 14 vorherigen privaten Dashboard-Sicherungen erhalten; die zwei verhinderten Versuche und der bewusste erfolgreiche Versuch erzeugten jeweils eine neue Sicherung. Der Konfliktvergleich erzeugte keine zusätzliche. Entwurf vor der Bereinigung privat gesichert, ursprüngliche Vorauswahl und automatische Sprache wiederhergestellt, Instrumentierung entfernt und Original-App neu aufgebaut. Eigenes Dashboard entfernt, „Test für APP“ und alle Bestandsdaten erhalten; weiterhin 0.1.10 und drei HA-Vollbackups auf .177. Zusammen mit den vorherigen Prüfungen sind alle drei Serverausgänge real geprüft: <strong>bereits gespeichert, nicht gespeichert, Konflikt</strong>.</p><p><img src="`+t+'" alt="Unveränderter HA-Stand erkannt, Entwurf erhalten und erneutes Speichern möglich"></p><p><img src="'+i+'" alt="Konflikt erkannt, Entwurf erhalten und Überschreiben gesperrt"></p><p><strong>0.1.10 – Abbruch während der HA-Schreibbestätigung auf .177 geprüft:</strong> Nach frischem Vollbackup wurde die echte WebSocket-Verbindung der App zu HA für genau einen Schreibauftrag des eigenen Testdashboards unmittelbar nach dem Senden und vor dem Empfang der Ergebnisnachricht abgebrochen. Kein erfolgreicher Schreibstatus wurde an die App zurückgegeben und kein anschließendes Rücklesen im Commit ausgeführt. HA hatte die beiden gewünschten Benutzerlisten dennoch gespeichert, wie der unabhängige Dateivergleich belegt.</p><p>Die App meldete <strong>Speicherergebnis unklar</strong>, behielt den Checkbox-Entwurf vollständig und sperrte erneutes Speichern. <strong>Serverstand prüfen</strong> stellte über eine neue Verbindung fest: <strong>Bereits gespeichert; kein erneuter Schreibvorgang.</strong> Genau eine zusätzliche private Dashboard-Sicherung, alle 13 bisherigen Sicherungen erhalten; die HA-Datei blieb durch die Serverprüfung bytegleich. Karten, Namen, Pfade und Unteransicht unverändert. Anschließend temporäre Instrumentierung entfernt, Original-App neu aufgebaut und Testdashboard bereinigt. Bestandsdaten einschließlich „Test für APP“ und die ursprüngliche Vorauswahl bleiben erhalten; Paketversion weiterhin 0.1.10.</p><p><img src="'+a+'" alt="Entwurf nach Abbruch des HA-WebSocket vor der Schreibbestätigung erhalten"></p><p><img src="'+s+'" alt="Neue Serververbindung erkennt bereits gespeicherten Entwurf ohne doppeltes Schreiben"></p><p><strong>0.1.10 – Bestätigungsabbruch auf .177 geprüft:</strong> Nach frischem Vollbackup wurde eine einmalige, ausschließlich auf ein eigenes Testdashboard begrenzte Instrumentierung verwendet: Die App schrieb zwei Zuordnungen tatsächlich nach HA, las sie erfolgreich zurück und brach dann die echte HTTP-Antwortverbindung zum Ingress ab, bevor die Oberfläche die Bestätigung erhielt. Dies ist ein gezielter Rückkanalfehler mit realen HA-Daten, kein nur gemockter Test und kein physisches Ziehen eines Netzwerkkabels.</p><p>Die Oberfläche meldete <strong>Speicherergebnis unklar</strong>, behielt sämtliche Checkbox-Auswahlen und sperrte erneutes Speichern. <strong>Serverstand prüfen</strong> erkannte den bereits gespeicherten Entwurf ohne weiteren Schreibvorgang. Genau eine zusätzliche Dashboard-Sicherung; die HA-Datei blieb nach der Prüfung bytegleich. Karten, Namen, Pfade und Unteransicht unverändert. Anschließend Testinstrumentierung vollständig entfernt, Original-App neu aufgebaut und eigenes Dashboard gelöscht: alle 23 geprüften HA-Dateien einschließlich „Test für APP“ und alle 19 App-Quelldateien bytegleich zum Ausgangsstand; sieben ATLAS-Projekte, Plugins, Papierkorb, Vorauswahl und automatische Sprache erhalten. Version und veröffentlichte Paketdateien bleiben unverändert bei 0.1.10.</p><p><img src="'+l+'" alt="Unklarer Ausgang nach unterbrochener HTTP-Bestätigung, Entwurf erhalten auf .177"></p><p><img src="'+h+'" alt="Serverprüfung erkennt bereits gespeicherten Entwurf ohne erneutes Schreiben"></p><p><strong>0.1.10 – Wiederherstellung geprüft, „Experimentell“ entfernt:</strong> Am 20.10.2026 auf .177 zunächst frisch vollständig gesichert. Reine App-Wiederherstellung aus diesem Backup: Die zwölf ursprünglichen privaten Dashboard-Sicherungen sind wieder vorhanden, der zusätzliche Prüfmarker ist entfernt und die aktuelle HA-Testkonfiguration bleibt unverändert. Anschließend vollständige Wiederherstellung von HA 2026.10.2 einschließlich Einstellungen/Verlauf, Share, Medien, SSL und sämtlichen Apps ausgeführt. HA und die App starten wieder; „Test für APP“ zeigt unverändert 18 Ansichten und vier Benutzer, automatische Sprache und Vorauswahl bleiben erhalten.</p><p>Nach dem Neustart sind 21 HA-Dateien einschließlich aller vorhandenen Lovelace-Dateien bytegleich. Die zwei übrigen geprüften Register behalten sämtliche 22 Geräte und 73 Entitäten samt Einstellungen; nur Laufzeit-Änderungszeitstempel und die von HA erfasste App-Version aktualisieren sich. Sieben ATLAS-Projekte, Pluginverwaltung und Papierkorbstand sind unverändert. Die bestehende ATLAS-HA-Verbindung funktioniert ohne erneute Zugangsdaten. Das erst nach dem Backup angelegte Testdashboard wird durch die Vollwiederherstellung entfernt. Es handelt sich um eine Rücksicherung auf der vorhandenen Testinstallation, keinen Neuaufbau auf leerer Hardware. 33 Python- und 19 Node-Tests sowie Docker-Builds amd64/aarch64 bestanden. 0.1.10 entfernt nur die experimentelle Paketkennzeichnung und aktualisiert Version/Nachweise; Speicherlogik und Berechtigungen bleiben unverändert. .68 und Produktivsysteme wurden nicht verwendet.</p><p>Die Prüfungen decken verhinderte Schreibaufträge, eine zwischenzeitliche Änderung aus zweiter Sitzung, HA-WebSocket-Abbruch vor Empfang der Schreibbestätigung und HTTP-Rückkanalabbruch nach erfolgreichem HA-Rücklesen ab. Alle drei Serverausgänge sind an eigenen Testdaten beobachtet, keine Garantie für jeden möglichen Abbruchzeitpunkt. Ein physischer LAN-/Stromausfall wurde nicht ausgelöst. Die Anleitung zu unklaren Schreibausgängen gilt weiterhin.</p><p><img src="'+u+'" alt="App nach vollständiger HA-Wiederherstellung auf .177 mit erhaltenem Originaldashboard"></p><h3 id="fruhere-prufungen-–-damaliger-stand" tabindex="-1">Frühere Prüfungen – damaliger Stand <a class="header-anchor" href="#fruhere-prufungen-–-damaliger-stand" aria-label="Permalink to &quot;Frühere Prüfungen – damaliger Stand&quot;">​</a></h3><p><strong>Konflikte und Verbindungsunterbrechung mit 0.1.8 auf .177 geprüft:</strong> Nach frischem Vollbackup wurden zwei App-Tabs mit demselben eigenen Testdashboard geöffnet. Eine Änderung in Tab A wurde gespeichert; der veraltete Entwurf aus Tab B wurde mit Konflikthinweis abgelehnt. Seine Auswahl blieb sichtbar, der Serverstand aus Tab A blieb bytegleich. Nach bewusstem Zurücksetzen/Neuladen ließ sich die zweite Änderung speichern, ohne die erste zu überschreiben.</p><p>Beim kontrollierten Stoppen der App wurde ein noch laufender Speichervorgang vollständig abgeschlossen und bestätigt. Der anschließende Speicherversuch gegen die gestoppte App änderte keine Daten. Nach Wiederstart erschien die Fehlermeldung zur Erreichbarkeit/Sitzung, der ungespeicherte Entwurf blieb erhalten und es erfolgte kein automatisches Nachspeichern. Nach Serververgleich und erneutem Laden war gezieltes Speichern wieder möglich. Karten, Namen und Unteransicht blieben erhalten; das eigene Testdashboard wurde anschließend entfernt.</p><p><strong>0.1.9 – Timeout-/Abbruchbefund behoben:</strong> Nach frischem Vollbackup auf .177 installiert. Bei vollständig gestoppter App greift das lokale 30-Sekunden-Limit; manueller Abbruch und Erreichbarkeitsfehler erhalten ebenfalls beide geänderten Zeilen. Kein Schreibauftrag, Serverdatei bytegleich. Der heruntergeladene Entwurf enthält beide geplanten Zuordnungen und keine Tokens. Nach App-Neustart und erneuerter Sitzung ist gezieltes Speichern erfolgreich; Karten, Namen, Pfade und Unteransicht bleiben erhalten. Eigenes Testdashboard entfernt, ursprüngliche Vorauswahl und automatische Sprache wiederhergestellt; die vier vorhandenen Lovelace-Dateien einschließlich „Test für APP“ sind bytegleich zur Sicherung.</p><p>33 Python- und 19 Node-Prüfungen bestehen, einschließlich Fetch-/Antwort-Timeout, später Antworten, Abbruch, unklarem Schreibausgang, Serververgleich ohne erneutes Schreiben, Konflikten und verloren gegangener Bestätigung nach erfolgtem HA-Schreiben. Docker-Builds amd64/aarch64 und UGSo-App-CI erfolgreich. Ein harter Netzabbruch exakt zwischen HA-Schreiben und Bestätigung bleibt real unbewiesen; dieser Pfad ist automatisiert geprüft. Die vollständige App-/HA-Backup-Wiederherstellung bleibt offen, der experimentelle Status erhalten. .68 und Produktivsysteme unverändert.</p><p><img src="'+d+'" alt="Zeitlimit erreicht, Entwurf erhalten – echte Prüfung 0.1.9 auf .177"></p><p><img src="'+o+'" alt="Veralteten Speicherstand abgelehnt, Entwurf erhalten – echte Prüfung auf .177"></p><p><strong>0.1.8 – Speichern-Erfolgsmeldung korrigiert:</strong> Der vollständige Satz samt Ansichtenanzahl wird als eine Übersetzung in DE/EN/FR angezeigt, unabhängig von der Sprache der API-Antwort. Eine bereits angezeigte Erfolgsmeldung folgt auch nach dem Speichern der aktuellen Sprachwahl ohne Neuladen. Der Hinweis auf gemischte Sprache in 0.1.7 weiter unten ist damit behoben.</p><p>Auf .177 nach frischem Vollbackup aktualisiert und mit einem eigenen Dashboard aus zwei Ansichten geprüft: drei echte Speichervorgänge in DE/EN/FR und Sprachwechsel nach dem Speichern bestanden. Jeweils zwei Zuordnungen geändert, keine Karten oder Namen. Automatische Sprache und ursprüngliche Vorauswahl wiederhergestellt; vorhandene Sicherungen erhalten. 28 Python- und zwölf Node-Prüfungen einschließlich englischer API-Antwort, nachträglichem Sprachwechsel und unverändertem Ergebnis bestanden; Docker-Builds für amd64/aarch64 und UGSo-App-CI erfolgreich. .68 und Produktivsysteme unverändert. Der experimentelle Status bleibt bis zum Abschluss der offenen Wiederherstellungs-/Konfliktprüfungen erhalten.</p><p><img src="'+w+'" alt="Vollständig deutsche Speichern-Erfolgsmeldung auf .177 mit 0.1.8"></p><p><strong>Speichern und Wiederherstellen mit 0.1.7 am 20.10.2026 auf .177 bestanden:</strong> Nach frischem HA-Vollbackup wurde ein eigenes temporäres Dashboard mit sechs Ansichten geprüft. Sammelauswahl/-abwahl für webuser und eine Einzelkorrektur änderten genau drei Ansichten. Nach Speichern und erneutem Laden waren nur die vorgesehenen Benutzerlisten geändert. Unberührte Sichtbarkeitswerte (<code>true</code>, <code>false</code>, <code>[]</code>), Karten einschließlich verschachtelter Inhalte, Pfade, Unteransicht und Originalnamen mit äußeren Leerzeichen blieben erhalten.</p><p>Die heruntergeladene automatische Sicherung enthielt exakt die ursprüngliche vollständige Dashboard-Konfiguration. Wiederherstellen erzeugte zuerst eine Gegensicherung des geänderten Standes und stellte danach die ursprüngliche Storage-Datei bytegleich wieder her. Das temporäre Dashboard wurde entfernt, die ursprüngliche Vorauswahl wiederhergestellt und alle vier vorhandenen Lovelace-Dateien einschließlich „Test für APP“ und Dashboard-Katalog blieben bytegleich. Auf .177 bleiben drei Vollbackups; private Wiederherstellungsnachweise und PC-Sicherungen bleiben erhalten. .68 und Produktivsysteme wurden nicht verändert.</p><p><img src="'+c+'" alt="Erfolgreiche Wiederherstellung des eigenen Testdashboards auf .177 mit 0.1.7"></p><p>Offen bleiben die vollständige App-/HA-Backup-Wiederherstellung und die reale Konflikt-/Abbruchprüfung. Kleine bekannte Darstellungsabweichung in 0.1.7: Die Speichern-Erfolgsmeldung kann einen englischen Satzteil in der deutschen Oberfläche enthalten; die Wiederherstellungsmeldung erschien korrekt deutsch. Die funktionale Prüfung ist bestanden.</p><p>0.1.7 nach frischem Vollbackup auf .177 aktualisiert: Icon in der HA-App-Kachel und im App-Kopf sichtbar, Kopfbereich in DE/EN/FR geprüft und fotografiert. Vorauswahl, 18 Ansichten, vier Benutzer und bestehende private Dashboard-Sicherung erhalten. Keine Zuordnung gespeichert; alle vier Lovelace-Dateien zur Sicherung unverändert. 28 Python- und elf Node-Prüfungen, korrekte PNG-Auslieferung, ZIP-Iconvergleich und amd64-/aarch64-Docker-Builds bestanden. Die persönliche Sprachwahl ist wieder auf automatisch gesetzt.</p><p><strong>Nutzerbestätigung vom 20.10.2026 für 0.1.6:</strong> Das Update auf der betroffenen Installation ist erfolgreich. „Übersicht aktuell“ wird nur noch einmal angezeigt; die zuvor gespeicherte Dashboard-Vorauswahl ist erhalten. Diese Rückmeldung bestätigt die Korrektur im ursprünglich gemeldeten Fall und ergänzt die automatisierten Alias-/Dublettenprüfungen sowie den Update-Test auf .177. Es wurde dafür kein zusätzlicher Zugriff durch den Agenten auf das Produktivsystem ausgeführt.</p><p>0.1.5 auf .177 nach frischem Vollbackup geprüft: leere Karte ausgeblendet, Fehler der nicht konfigurierten Übersicht getrennt angezeigt, Abbrechen und gespeicherte leere/erneut aktivierte Vorauswahl nach Neuladen bestätigt. Dialog in DE/EN/FR sichtbar geprüft. Keine Benutzerzuordnung gespeichert; die vier Lovelace-Dateien bleiben unverändert. 26 Python- und zehn Node-Prüfungen sowie amd64-/aarch64-Docker-Builds bestanden.</p><p>0.1.3 wurde vom Nutzer mit Sammel-/Einzelauswahl, Speichern und Neuladen erfolgreich geprüft. 0.1.4 wurde nach Vollbackup als lokale App auf .177 aktualisiert. Die automatische Sprachwahl folgt dort Deutsch → Englisch → Französisch → Deutsch ohne Neuladen der App. Namen und Zuordnungen bleiben erhalten; alle vier Lovelace-Dateien einschließlich „Test für APP“ sind nach der Prüfung SHA-256-identisch zur Sicherung. Ergänzend bestehen Offline-Frontend-, API-, Datenerhalt- und Konflikttests. Kein Produktivsystem wurde verändert. Die vollständige HA-Backup-Wiederherstellung der App ist noch offen. Eine nicht konfigurierte Standardübersicht kann <code>config_not_found</code> melden; ein vorhandenes manuelles Dashboard auswählen.</p><ul><li><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/dashboard_user_manager" target="_blank" rel="noreferrer">App-Quellcode und Paket auf GitHub</a></li><li><a href="/projects-mqtt/">UGSo HA Apps</a></li><li><a href="/en/projects/dashboard-user-manager/">English</a> · <a href="/fr/projects/dashboard-user-manager/">Français</a></li></ul>',82)])])}const V=g(A,[["render",v]]);export{H as __pageData,V as default};
